func translate(word string) string {
    // Rule 1: starts with vowel, or "xr" or "yt"
    if isVowel(word[0]) || strings.HasPrefix(word, "xr") || strings.HasPrefix(word, "yt") {
        return word + "ay"
    }

    // Now the word starts with a consonant (not x followed by r, not y followed by t)
    // Find the split point
    // We scan from the start. We want to move consonants to the end.
    // The split happens at the first vowel, but:
    //   - "qu" is treated as a consonant cluster (the u after q is part of the cluster)
    //   - "y" after consonants is treated as a vowel (so we stop before y)

    n := len(word)
    i := 0
    for i < n {
        c := word[i]
        if isVowel(c) {
            break
        }
        // c is a consonant
        // Check if it's 'q' followed by 'u'
        if c == 'q' && i+1 < n && word[i+1] == 'u' {
            i += 2
            break
        }
        // Check if it's 'y' (treated as vowel after consonants)
        if c == 'y' {
            break
        }
        i++
    }
    return word[i:] + word[:i] + "ay"
}
